usage:
import { Tower } from "./Tower";
import "./Tower.css";

<Tower
  gravity={50}
  slip={45}
  count={6}
/>

notes:
/* RIGID BODIES. A card is a box with a position, an ANGLE
   and the speed of each, in a room whose floor and walls are
   the grey card itself. Nothing in the block knows what a
   tower is, and nothing decides that a card tips: it turns
   because its centre of mass is past the edge of what it is
   standing on, and gravity does the rest. */
type Body = { x, y, a, vx, vy, w, hw, hh, invM, invI };  /* y up */

/* ONE STEP, at a fixed 240Hz whatever the screen does. Small
   steps are what let a stack stand still: a long one sinks a
   card far enough that the solver spends the next ten pushing
   it back out, and the tower shivers. */
for (const pair of touching) contacts = clip(faceOf(a), edgeOf(b));
for (const b of bodies) b.vy -= g * dt;        /* g: 900..4200 px/s² */
for (let i = 0; i < 12; i++) for (const c of contacts) {
  /* push apart along the normal, never pull together */
  c.pn = Math.max(0, c.pn + c.mn * (-vn + c.bias));
  /* and friction along the face, capped by how hard they press */
  c.pt = clamp(c.pt - c.mt * vt, -friction * c.pn, friction * c.pn);
}
for (const b of bodies) { b.x += b.vx * dt; b.y += b.vy * dt; b.a += b.w * dt; }

/* the contacts are REMEMBERED from one step to the next, and
   that memory is what holds a stack up. Move the floor, never
   rebuild it: a new floor is a floor with no memory. */

/* IN THE HAND a card is heavy and frictionless: its velocity is
   set toward the pointer every step, it shoves what it meets,
   and it slides along a wall instead of jamming on it. Letting
   go gives its weight and grip back and keeps the speed — which
   is what makes a flick a throw. No bounce anywhere: these are
   blocks, and a landing is the end of the motion. */
held.invM = 0.25;  held.friction = 0;
/* and it cannot CRUSH: the pull is capped, and any part of its
   velocity driving further into something it already touches is
   taken away — so pressing down on the tower stops at the top
   card instead of storing up an explosion */
steer(held, target, { speed: 1800, accel: 16000 });

/* the page is y-down and clockwise, the solver is neither */
.twr-row { transform: translate(Xpx, -Ypx) rotate(-A rad); }
